// Decorative dithered art for empty and loading states. The words next to it stay the accessible content.
import { ART } from './deck-art-data.js';

/** A hidden, text-free art element, or '' for a name without art. Generated by scripts/capy_art.py. */
export const artHTML = name => Object.hasOwn(ART, name) ? `<span class="cp-art" data-art="${name}" aria-hidden="true">${ART[name]}</span>` : '';
